commands:
cd /app && (nohup qemu-system-x86_64 -m 512 -nographic -serial telnet:127.0.0.1:6665,server,nowait -cdrom /app/alpine.iso -boot d >/tmp/alpine-qemu.log 2>&1 & echo $! > /tmp/alpine-qemu.pid) && sleep 2 && (python3 - <<'PY'
import socket,sys,time
host='127.0.0.1'; port=6665
for i in range(60):
    try:
        s=socket.create_connection((host,port),timeout=1)
        s.settimeout(2)
        data=b''
        t=time.time()+5
        while time.time()<t and len(data)<4096:
            try:
                chunk=s.recv(4096)
                if not chunk:
                    break
                data+=chunk
                if b'login:' in data.lower():
                    break
            except socket.timeout:
                pass
        s.close()
        sys.stdout.buffer.write(data)
        sys.exit(0)
    except Exception:
        time.sleep(1)
print('PORT_NOT_READY', file=sys.stderr)
sys.exit(1)
PY
)
